(() => {
 const data=window.v2Seeds, direction=document.documentElement.dataset.direction;
 const params=new URLSearchParams(location.search),view=params.get('view')||'home';
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const asset=p=>'../../../dist/'+p;
 const url=(v,id)=>'?view='+v+(id?'&item='+encodeURIComponent(id):'');
 let saved;try{saved=new Set(JSON.parse(localStorage.getItem('smoke-v2-saved')||'[]').filter(id=>data.some(d=>d.id===id)));}catch{saved=new Set();}
 let selected=params.get('region')||'shanghai';
 const seed=data.find(d=>d.id===params.get('item'))||data[0];
 const label=(s,n)=>`<p class="eyebrow">${n||'SMOKE ARCHIVE / 2.0'} <span>${s}</span></p>`;
 const photo=(d,cls='')=>`<img class="${cls}" src="${asset(d.packFront)}" alt="${esc(d.name)}包装参考正面" loading="lazy" decoding="async">`;
 const badge='<span class="reference">参考图 · 许可待确认</span>';
 function packageCard(d){return `<article class="label-card" style="--accent:${d.color}"><a class="label-image" href="${url('detail',d.id)}" aria-label="查看${esc(d.name)}烟标档案">${photo(d)}<span class="catalog-no">SA / ${d.number}</span></a><div class="label-caption"><p>${esc(d.region)} · ${esc(d.theme)}</p><h3><a href="${url('detail',d.id)}">${esc(d.name)}</a></h3><span>${esc(d.observations[0])}</span>${badge}</div></article>`;}
 const mapDocument=new DOMParser().parseFromString(chinaMapSvg,'image/svg+xml');
 function regionCard(d){const shape=mapDocument.querySelector('[data-province="'+d.provinceId+'"]');return `<a class="region-card" href="?view=regions&region=${d.provinceId}" style="--accent:${d.color}"><span>REGIONAL ROOM / ${d.number}</span><svg class="region-terrain" aria-hidden="true" focusable="false">${shape?.outerHTML||''}</svg><h3>${d.region}</h3><p>${d.theme} <span>01 件样板</span></p><b>进入展厅 ↗</b></a>`;}
 function characterCard(d){return `<article class="character-card" style="--accent:${d.color}"><button class="reveal" data-reveal="${d.id}" aria-label="揭示${esc(d.name)}角色" aria-pressed="false"><span>CHARACTER STUDY / ${d.number}</span><img src="${asset(d.preview)}" alt="${esc(d.name)}的v1角色剪影" loading="lazy" class="silhouette"><span class="reveal-hint">点按揭示轮廓 ＋</span></button><div><h3>${d.title}</h3><p>${d.translations[0][0]} → ${d.translations[0][1]}</p><a href="${url('detail',d.id)}#character">查看转译</a><button class="text-button" data-image="${asset(d.portrait)}" data-title="${esc(d.name)} · v1参考角色">直接查看立绘 ↗</button><small>v1 布局占位 · v2 方向：${d.type}</small></div></article>`;}
 function home(){const d=data[0];return `<section class="hero ${direction==='b'?'night-hero':''}"><div class="hero-copy">${label('本期策展 / 001','VISUAL CULTURE MUSEUM')}<h1>在方寸之间，<br>看见另一种<br><em>想象。</em></h1><p class="hero-intro">中国烟标视觉文化 × 原创角色档案<br>从一条金线、一座楼、一枚印，走进设计的另一面。</p><div class="hero-actions"><a class="button solid" href="${url('detail',d.id)}">走进本期展品 ↗</a><a class="underlined" href="?view=regions">按地域漫游</a></div><p class="micro">六件叙事样板 / 126 份原始档案 / G2 视觉方向预览</p></div><a href="${url('detail',d.id)}" class="hero-display" aria-label="进入中华软的视觉档案"><div class="display-grid" aria-hidden="true"></div><span class="vertical-caption">FORM / COLOR / MEMORY</span>${photo(d,'hero-pack')}<span class="display-label"><small>FEATURED EXHIBIT / 01</small><b>给屋檐留一条金线</b><span>朱红 · 建筑 · 城市边界</span></span><span class="display-index">01—06</span></a></section><section class="intro-strip"><p>包装是入口。<br><strong>故事，从观察开始。</strong></p><div><span>01 看见包装</span><span>02 解构符号</span><span>03 进入虚构</span></div><p>事实有来源，解读留边界。<br>每一个角色，都是非官方原创。</p></section><section class="room-section"><div class="section-title">${label('从地图进入地方','REGIONAL ROOMS')}<h2>每一处地方，<br>都有自己的视觉语气。</h2><a class="underlined" href="?view=regions">打开地域展厅 ↗</a></div><div class="region-grid">${data.slice(0,3).map(regionCard).join('')}</div></section><section class="selection-section"><div class="section-title">${label('本期视觉档案','CURATOR’S SELECTION')}<h2>先看见，再想象。</h2><a href="?view=labels" class="underlined">六件烟标样板 ↗</a></div><div class="label-grid">${data.slice(0,3).map(packageCard).join('')}</div></section><section class="exhibition-teaser"><span>EXHIBITION / 01</span><h2>建筑的回声</h2><p>从横向屋檐到层层羽翼：两件烟标怎样把建筑变成叙事的骨架？</p><a href="?view=themes" class="button">走进专题 ↗</a></section>`;}
 function regions(){return `<section class="page-heading">${label('用地域打开档案','REGIONAL ROOMS')}<h1>一张地图，<em>很多种观看。</em></h1><p>地域标记沿用资料中的品牌关联，不等同于生产地。原型仅开放六个种子展厅。</p></section><section class="map-layout"><div class="map-board"><div class="map-caption"><span>中国省级地区示意</span><small>地图 / geoBoundaries</small></div><div id="region-map">${chinaMapSvg}</div><a class="micro" href="https://www.geoboundaries.org/" target="_blank" rel="noopener noreferrer">地图数据来源 ↗</a></div><div class="map-selection"><div class="region-pills">${data.map(d=>`<button data-region="${d.provinceId}" aria-pressed="${d.provinceId===selected}">${d.region}</button>`).join('')}</div><div id="region-detail" aria-live="polite"></div></div></section><div class="region-grid all-regions">${data.map(regionCard).join('')}</div>`;}
 function regionDetail(){const d=data.find(d=>d.provinceId===selected);const target=document.querySelector('#region-detail');if(!target)return;target.innerHTML=d?`<div class="region-intro">${label('地域展签 / '+d.number)}<h2>${d.region}</h2><p>${d.theme}。从包装中可见的色块、线条与图案开始，阅读这件作品。</p></div>${packageCard(d)}`:`<div class="empty"><h2>这个展厅尚在筹备</h2><p>126份旧版档案已保留。本轮六件种子之外的地区将在方向确认后迁移，不代表当地没有烟标。</p><a href="../../../dist/index.html">浏览旧版完整档案 ↗</a></div>`;document.querySelectorAll('[data-region]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.region===selected)));document.querySelectorAll('#region-map [data-province]').forEach(p=>{const active=p.dataset.province===selected;p.classList.toggle('active',active);p.setAttribute('aria-pressed',String(active));});}
 function labels(){return `<section class="page-heading">${label('让包装成为观看的中心','LABEL INDEX')}<h1>方寸之间的<em>颜色与秩序。</em></h1><p>六件参考包装，六种构图。清晰度与转载许可尚未认证，保留原照可见边界。</p></section><div class="filter-bar"><label>筛选主题 <select id="theme-filter"><option value="">全部主题</option>${[...new Set(data.map(d=>d.theme))].map(t=>`<option>${t}</option>`).join('')}</select></label><span id="filter-count">06 件样板 / 非销量排名</span><button id="density" aria-pressed="false">切换密集陈列</button></div><section class="label-grid index-grid" id="label-index">${data.map(packageCard).join('')}</section>`;}
 function characters(){return `<section class="page-heading">${label('先认轮廓，再看人物','CHARACTER STUDIES')}<h1>想象，有自己的<em>轮廓。</em></h1><p>点按剪影揭示角色。当前图像为保留的 v1 作品；下方展签说明 v2 的设计候选方向，尚未生成新图。</p></section><section class="character-grid">${data.map(characterCard).join('')}</section>`;}
 function detail(){return `<div class="detail-breadcrumb"><a href="?view=labels">烟标索引</a><span>/</span><span>${seed.region}</span><span>/ ${seed.name}</span></div><section class="exhibit-top"><div class="object-stage"><span class="object-number">SA / ${seed.number}</span>${photo(seed)}${badge}<button class="button" data-image="${asset(seed.packFront)}" data-title="${esc(seed.name)} · 原始参考图">查看包装正面 ＋</button></div><div class="exhibit-intro">${label('一件展品的六层叙事','EXHIBIT / '+seed.number)}<h1>${seed.title}</h1><p class="exhibit-name">${seed.name} <span>${seed.region} · ${seed.theme}</span></p><p class="standfirst">${seed.observations.join('；')}。从这些可见细节开始，阅读另一种想象。</p><div class="layer-links"><a href="#observations">01 看见</a><a href="#reading">02 解读</a><a href="#character">03 转译</a><a href="#fiction">04 故事</a></div><button class="button" data-save="${seed.id}" aria-pressed="${saved.has(seed.id)}">${saved.has(seed.id)?'已收入收藏':'收入本地收藏'} ♡</button><p class="micro">包装版本未认证 · 地域为品牌关联 · 角色非官方原创</p></div></section><div class="narrative"><section class="narrative-section" id="observations"><div>${label('事实 / 目视观察','01 / OBSERVE')}<h2>先看见什么。</h2></div><div><ol class="observations">${seed.observations.map(s=>`<li>${s}</li>`).join('')}</ol><p class="evidence">依据：本地参考照片人工目视，2026-10-15。小图无法辨认的文字和建筑细节不补写。</p>${seed.sourceReferences.map(s=>`<a class="source-link" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a><p class="micro">原资料访问日期 ${s.accessed}；本轮未新增线上交叉核验。</p>`).join('')}</div></section><section class="narrative-section" id="reading"><div>${label('解读 / 策展视角','02 / INTERPRET')}<h2>形状怎样<br>成为意味。</h2></div><div><p class="reading-text">${seed.reading}</p><p class="evidence">策展解读，不代表品牌官方设计释义。品牌历史与具体年代待进一步核实。</p></div></section><section class="narrative-section" id="character"><div>${label('创作 / 设计方向草案','03 / TRANSLATE')}<h2>把符号，<br>交给想象。</h2><p>${seed.type}<br>备选方向：${seed.alternative}</p></div><div><div class="translation-list">${seed.translations.map((t,i)=>`<article><span>0${i+1}</span><p>${t[0]}</p><b>↘</b><h3>${t[1]}</h3></article>`).join('')}</div><button class="character-preview" data-image="${asset(seed.portrait)}" data-title="${seed.name} · v1参考角色"><img src="${asset(seed.preview)}" alt="${seed.name}保留的v1参考角色" loading="lazy"><span>查看 v1 布局参考 ＋<small>此图不是上述 v2 方向的新立绘。<br>新角色待 G5 美术试产。</small></span></button></div></section><section class="narrative-section fiction" id="fiction"><div>${label('虚构 / 非官方原创短篇','04 / FICTION')}<h2>${seed.title}</h2></div><div><p>${seed.lore}</p><span class="fiction-stamp">原创虚构 · 与品牌历史无关</span></div></section><section class="narrative-section"><div>${label('来源边界','05 / NOTES')}<h2>记忆，也需要<br>保留空白。</h2></div><div><p>本件尚未收录可核实的民间俗语。暂不沿用缺少流传证据的段子，也不把产品别称自动当成地方史。</p><details><summary>关于图像、角色与资料的声明</summary><p>包装为原有资料参考图；清晰度和转载许可待确认，不能据此宣称高清或授权完成。原型仅用于内部视觉评审。角色和短篇为非官方原创；v1参考图与v2方向草案分别标明。吸烟有害健康。</p></details></div></section></div><section class="selection-section"><div class="section-title">${label('继续漫游','06 / RELATED')}<h2>下一件，换个角度。</h2></div><div class="label-grid">${seed.relatedIds.map(id=>packageCard(data.find(d=>d.id===id))).join('')}</div></section>`;}
 function themes(){return `<section class="page-heading">${label('策展专题 / 概念预览','EXHIBITIONS')}<h1>把作品，放回<em>彼此之间。</em></h1><p>围绕可见图案建立联系，完整史料与专题叙事将在 G4 精修。</p></section>${['建筑的回声','印刷的秩序'].map(t=>`<section class="selection-section"><h2>${t}</h2><p>${t==='建筑的回声'?'屋檐、层楼与横向的安定感。':'方印、横带与边框，图形怎样安排我们的视线。'}</p><div class="label-grid">${data.filter(d=>d.theme===t).map(packageCard).join('')}</div></section>`).join('')}`;}
 function collection(){return `<section class="page-heading">${label('仅保存在当前浏览器','YOUR COLLECTION')}<h1>把看见的，<em>留下来。</em></h1><p>本地收藏与旧版分开保存。没有账号，也不记录购买偏好。</p></section><section class="label-grid">${data.filter(d=>saved.has(d.id)).map(packageCard).join('')||'<div class="empty"><p>这里还没有展品。</p><a class="button" href="?view=labels">去烟标索引看看 ↗</a></div>'}</section>`;}
 function votes(){return `<section class="page-heading">${label('G7 前不开放公众投票','VISITOR’S CHOICE')}<h1>你记住的，<em>是哪一种设计？</em></h1><p>这里将记录烟标图案与文化主题的审美偏好，不评选口感、销量或购买价值。</p></section><section class="empty vote-preview"><h2>计票尚未开放</h2><p>今日 / 七日 / 累计。正式实现需服务端每日一票、北京时间日界线、异常票撤回与口径公示，并经过 G7 审查。本阶段没有虚构票数。</p><a class="button" href="?view=labels">先看设计档案 ↗</a></section>`;}
 const screens={home,regions,labels,characters,detail,themes,collection,votes};
 document.querySelector('#app').innerHTML=`<div class="review-strip">2.0 内部原型 / ${direction==='a'?'A 暖白策展':'B 深墨展厅'}<a href="../">切换方向 ↗</a></div><header class="site-header"><a class="brand" href="?view=home"><span class="brand-seal">档</span><span>SMOKE ARCHIVE<small>中国烟标视觉文化档案</small></span></a><nav aria-label="主导航">${[['home','首页'],['regions','地域'],['labels','烟标'],['characters','角色'],['themes','专题'],['votes','设计榜'],['collection','收藏']].map(([v,n])=>`<a href="?view=${v}" ${view===v?'aria-current="page"':''}>${n}</a>`).join('')}</nav><span class="header-edition">VOL. 02 / 2026</span></header><main id="main">${(screens[view]||home)()}</main><footer><a class="brand" href="?view=home">SMOKE ARCHIVE <small>2.0 / 视觉文化数字展馆</small></a><p>事实有出处。解读有边界。故事是原创。<br>非官方文化与设计档案 · 吸烟有害健康</p><a href="../../../dist/index.html">旧版档案 ↗</a></footer><dialog id="image-view" aria-labelledby="image-title"><div class="image-toolbar"><h2 id="image-title">参考图细看</h2><button id="image-zoom" aria-pressed="false">放大 2×</button><button id="image-close" aria-label="关闭图片">×</button></div><div class="image-stage"><img alt=""></div><p>原始资料尺寸展示 · 放大不代表高清 · 放大后滑动查看</p></dialog>`;
 document.querySelectorAll('.region-terrain').forEach(svg=>{const shape=svg.querySelector('[data-province]');if(!shape)return;const b=shape.getBBox();svg.setAttribute('viewBox',`${b.x-2} ${b.y-2} ${b.width+4} ${b.height+4}`);shape.setAttribute('tabindex','-1');shape.removeAttribute('role');});
 if(view==='regions'){regionDetail();document.querySelectorAll('#region-map [data-province]').forEach(p=>{p.setAttribute('tabindex','0');p.setAttribute('role','button');p.setAttribute('aria-label','选择'+(data.find(d=>d.provinceId===p.dataset.province)?.region||'待迁移地区'));});}
 document.addEventListener('click',e=>{const region=e.target.closest('[data-region],#region-map [data-province]');if(region){selected=region.dataset.region||region.dataset.province;history.replaceState(null,'','?view=regions&region='+selected);regionDetail();return;}const reveal=e.target.closest('[data-reveal]');if(reveal){if(reveal.getAttribute('aria-pressed')==='true'){location.href=url('detail',reveal.dataset.reveal);return;}reveal.setAttribute('aria-pressed','true');const img=reveal.querySelector('img');img.classList.remove('silhouette');img.alt=img.alt.replace('角色剪影','参考角色');reveal.querySelector('.reveal-hint').textContent='已揭示 · 再次点按进入档案 ↗';return;}const save=e.target.closest('[data-save]');if(save){saved.has(save.dataset.save)?saved.delete(save.dataset.save):saved.add(save.dataset.save);try{localStorage.setItem('smoke-v2-saved',JSON.stringify([...saved]));}catch{}save.setAttribute('aria-pressed',String(saved.has(save.dataset.save)));save.textContent=saved.has(save.dataset.save)?'已收入收藏 ♥':'收入本地收藏 ♡';}const image=e.target.closest('[data-image]');if(image){const dialog=document.querySelector('#image-view');document.querySelector('#image-title').textContent=image.dataset.title;dialog.querySelector('img').src=image.dataset.image;dialog.querySelector('img').alt=image.dataset.title;dialog.querySelector('.image-stage').classList.remove('zoomed');document.querySelector('#image-zoom').setAttribute('aria-pressed','false');document.querySelector('#image-zoom').textContent='放大 2×';dialog.showModal();document.body.classList.add('modal-open');}});
 document.querySelector('#image-close').onclick=()=>document.querySelector('#image-view').close();
 document.querySelector('#image-zoom').onclick=e=>{const stage=document.querySelector('.image-stage'),on=stage.classList.toggle('zoomed');e.target.setAttribute('aria-pressed',String(on));e.target.textContent=on?'适应屏幕':'放大 2×';requestAnimationFrame(()=>{stage.scrollLeft=on?(stage.scrollWidth-stage.clientWidth)/2:0;stage.scrollTop=on?(stage.scrollHeight-stage.clientHeight)/2:0;});};
 document.querySelector('#image-view').addEventListener('close',()=>document.body.classList.remove('modal-open'));
 document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('#region-map [data-province]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
 document.querySelector('#theme-filter')?.addEventListener('change',e=>{const filtered=data.filter(d=>!e.target.value||d.theme===e.target.value);document.querySelector('#label-index').innerHTML=filtered.map(packageCard).join('');document.querySelector('#filter-count').textContent=filtered.length+' 件样板 / 非销量排名';});
 document.querySelector('#density')?.addEventListener('click',e=>{const on=document.querySelector('#label-index').classList.toggle('dense');e.target.setAttribute('aria-pressed',String(on));});
})();
